* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

[font=Inter][weight=normal] {
  font-family: "Inter", sans-serif;
  font-weight: 400;
  font-style: normal;
}

[fontSize=sm] {
  font-size: 0.75rem;
}

[fontSize=md] {
  font-size: 1.25rem;
}

[fontSize=lg] {
  font-size: 1.5rem;
}

[stack] {
  display: flex;
  flex-direction: column;
}

[stack][reverse] {
  display: flex;
  flex-direction: column-reverse;
}

[stack][centered] {
  align-items: center;
  justify-content: center;
}

[row] {
  display: flex;
  flex-direction: row;
}

[grid] {
  display: grid;
}

[float=left] {
  float: left;
}

